// Reusable Diagnostic Console Component with auto-scroll logic
const DiagnosticConsole = ({ logs }) => {
  const containerRef = useRef(null);

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [logs]);

  return (
    <div 
      ref={containerRef}
      className="mt-3 p-3 bg-slate-900 text-emerald-400 font-mono text-[9px] rounded-xl border border-slate-800 max-h-[140px] overflow-y-auto space-y-1 shadow-inner select-text"
    >
      {logs.length === 0 ? (
        <div className="text-slate-500 italic">No logs available yet.</div>
      ) : (
        logs.map((log, index) => (
          <div key={index} className="leading-relaxed border-b border-slate-800/30 pb-0.5 last:border-0">{log}</div>
        ))
      )}
    </div>
  );
};

